package com.vadim.duraktracker;
import android.app.Service;import android.content.Intent;import android.graphics.Color;import android.graphics.PixelFormat;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.os.IBinder;import android.view.Gravity;import android.view.MotionEvent;import android.view.View;import android.view.WindowManager;import android.widget.LinearLayout;import android.widget.TextView;
public class FloatingOverlayService extends Service {
 public static final String ACTION_UPDATE="com.vadim.duraktracker.UPDATE";private WindowManager wm;private View panel;private TextView values;private int mine=0,deck=24,enemy=0,out=0;
 @Override public void onCreate(){super.onCreate();wm=(WindowManager)getSystemService(WINDOW_SERVICE);buildPanel();}
 private TextView makeText(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setGravity(Gravity.CENTER);return t;}
 private void buildPanel(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(12,8,12,10);GradientDrawable bg=new GradientDrawable();bg.setColor(Color.argb(238,16,27,45));bg.setCornerRadius(18);bg.setStroke(2,Color.rgb(75,130,190));box.setBackground(bg);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);TextView title=makeText("♠ DURAK TRACKER",13,Color.WHITE);title.setGravity(Gravity.CENTER_VERTICAL);TextView close=makeText("×",22,Color.WHITE);close.setPadding(14,0,4,0);close.setOnClickListener(v->stopSelf());head.addView(title,new LinearLayout.LayoutParams(0,-2,1));head.addView(close);box.addView(head);values=makeText("МОИ 0   КОЛОДА 24\nПРОТИВНИК 0   ВЫШЛИ 0",12,Color.WHITE);values.setPadding(0,10,0,4);box.addView(values);TextView hint=makeText("Перетащи за заголовок",9,Color.LTGRAY);box.addView(hint);final WindowManager.LayoutParams lp=params();final int[] xy={0,0};head.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN){xy[0]=(int)e.getRawX()-lp.x;xy[1]=(int)e.getRawY()-lp.y;return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){lp.x=(int)e.getRawX()-xy[0];lp.y=(int)e.getRawY()-xy[1];try{wm.updateViewLayout(panel,lp);}catch(Exception ignored){}return true;}return e.getAction()==MotionEvent.ACTION_UP;});panel=box;try{wm.addView(panel,lp);}catch(Exception ex){stopSelf();}}
 private WindowManager.LayoutParams params(){int type=android.os.Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE;WindowManager.LayoutParams p=new WindowManager.LayoutParams((int)(250*getResources().getDisplayMetrics().density),WindowManager.LayoutParams.WRAP_CONTENT,type,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.END;p.x=12;p.y=130;return p;}
 @Override public int onStartCommand(Intent i,int flags,int id){if(i!=null&&ACTION_UPDATE.equals(i.getAction())){mine=i.getIntExtra("mine",mine);deck=i.getIntExtra("deck",deck);enemy=i.getIntExtra("enemy",enemy);out=i.getIntExtra("out",out);if(values!=null)values.setText("МОИ "+mine+"   КОЛОДА "+deck+"\nПРОТИВНИК "+enemy+"   ВЫШЛИ "+out);}return START_STICKY;}
 @Override public void onDestroy(){if(panel!=null)try{wm.removeView(panel);}catch(Exception ignored){}super.onDestroy();}@Override public IBinder onBind(Intent i){return null;}
}
